import{z as B,x as d,o as n,c as D,q as r,j as l,D as i,d as t,s as o,S as s,b as e}from"./chunks/framework.C8m1ZpeB.js";const h=JSON.parse('{"title":"位图索引","description":"","frontmatter":{"title":"位图索引","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/bitmap-index.md","filePath":"cs/bitmap-index.md","lastUpdated":1791063341000}'),p={name:"cs/bitmap-index.md"};function A(m,a,N,C,u,V){const E=d("Mermaid");return n(),D("div",null,[a[2]||(a[2]=r('<h1 id="位图索引" tabindex="-1">位图索引 <a class="header-anchor" href="#位图索引" aria-label="Permalink to &quot;位图索引&quot;">​</a></h1><div class="epigraph"><p>每个值一条位向量，行号对位；AND/OR 做谓词交并，扫描变成位运算，适合低 NDV 的分析列。</p><footer>—— 据 O&#39;Neil 位图索引；Wu, O&#39;Neil 等压缩位图；Ramakrishnan and Gehrke</footer></div><p><a href="/cs/zone-maps">上一课</a>用粗摘要跳过区。本课不维护 min/max。缺口是低基数列（国家、状态、日期天）上的精确过滤：B+ 叶子对每个键挂 RID 列表，列表很长时交谓词要排 RID。位图：值 \\(v\\) 对应长度为 \\(N\\) 的位向量，第 \\(i\\) 位表示行 \\(i\\) 是否取 \\(v\\)。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>NDV 高（主键）则位图张数爆炸、几乎全 0，不如 B+。NDV 低则向量少，压缩后（Roaring、BBC、WAH）更小。多谓词：<code>color=red AND size=L</code> 是两向量 AND，再从置位取行。缺口是<strong>只读或追加型分析表</strong>上维护便宜；OLTP 频繁改行则要改多张向量，写放大差。</p><p><span class="marginnote">术语翻译：NDV 就是「这一列总共有多少个不同的值」。「国家」列 NDV 只有几百，建几百条位向量就够了；主键列 NDV 等于行数，每行一条位图、每条几乎只有一个 1——这时的位图既大又没用，该交给 B+ 树。</span></p><p>NULL 单独一向量。与连接：星型后课可用位图做维表过滤再探事实表。本课单表过滤。</p><p><span class="marginnote">Patrick O&#39;Neil 位图索引工作。压缩位图让稀疏也可接受。本课不把位图当全文倒排——倒排下一课，键是词项不是低 NDV 维值。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>建：全表扫，为每个值置位。查询：取向量、位运算、解码 RID。与 zone：先 zone 跳区，区内再位图或再扫。向量化：把置位转成选择向量。</p><p>维护：原地更新翻比特；插入追加位。删除可翻或延迟与 vacuum 一起重建。MVCC：位图必须对应某一行版本集合，否则看见幽灵——常对只读副本或物化快照建位图。</p>',11)),(n(),l(s,null,{default:i(()=>[o(E,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20V1%5B%22%E5%80%BC%20A%20%E7%9A%84%E4%BD%8D%E5%9B%BE%22%5D%20--%3E%20AND%5B%22%E6%8C%89%E4%BD%8D%20AND%20%2F%20OR%22%5D%0A%20%20V2%5B%22%E5%80%BC%20B%20%E7%9A%84%E4%BD%8D%E5%9B%BE%22%5D%20--%3E%20AND%0A%20%20AND%20--%3E%20RID%5B%22%E7%BD%AE%E4%BD%8D%E8%A1%8C%E5%8F%B7%22%5D%0A%20%20RID%20--%3E%20FETCH%5B%22%E5%9B%9E%E8%A1%A8%E6%88%96%E8%A6%86%E7%9B%96%E5%88%97%22%5D%0A"})]),fallback:i(()=>[...a[0]||(a[0]=[t(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=e("p",null,[e("span",{class:"marginnote"},"直觉类比：每个值的位向量就是一页点名册——第 \\(i\\) 格写 1 表示第 \\(i\\) 行「是这个值」。两个条件的 AND 就是把两页名册对齐，一格一格比：「两页都写 1 的行才留下」。一次 CPU 位运算同时「点名」64 行，这正是它对分析查询快的原因。")],-1)),a[4]||(a[4]=e("h2",{id:"机制",tabindex:"-1"},[t("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[5]||(a[5]=e("p",null,"优化器：位图扫描代价 ≈ 向量体积 + 置位密度 × 回表。选择率估错会低估回表随机 I/O。覆盖：若查询列都在别处，可能只定位行号。",-1)),a[6]||(a[6]=e("p",null,"并行：按行号分段切向量。exchange 传位图段比传行宽。",-1)),a[7]||(a[7]=e("p",null,"该不该选位图，可以按两个轴决策。",-1)),(n(),l(s,null,{default:i(()=>[o(E,{id:"mermaid-47",class:"mermaid",graph:"flowchart%20TD%0A%20%20COL%5B%22%E8%A6%81%E5%BB%BA%E7%B4%A2%E5%BC%95%E7%9A%84%E5%88%97%22%5D%20--%3E%20NDV%7B%22NDV%20%E4%BD%8E%E5%90%97%22%7D%0A%20%20NDV%20--%3E%7C%22%E6%98%AF%22%7C%20RO%7B%22%E6%9B%B4%E6%96%B0%E9%A2%91%E7%B9%81%E5%90%97%22%7D%0A%20%20NDV%20--%3E%7C%22%E5%90%A6%22%7C%20BTREE%5B%22%E7%94%A8%20B%2B%20%E6%A0%91%22%5D%0A%20%20RO%20--%3E%7C%22%E5%8F%AA%E8%AF%BB%20%2F%20%E8%BF%BD%E5%8A%A0%22%7C%20BM%5B%22%E4%BD%8D%E5%9B%BE%E5%90%88%E9%80%82%22%5D%0A%20%20RO%20--%3E%7C%22OLTP%20%E9%AB%98%E9%A2%91%E6%94%B9%22%7C%20NO%5B%22%E5%86%99%E6%94%BE%E5%A4%A7%E5%B7%AE%EF%BC%8C%E6%85%8E%E7%94%A8%E4%BD%8D%E5%9B%BE%22%5D%0A"})]),fallback:i(()=>[...a[1]||(a[1]=[t(" Loading... ",-1)])]),_:1})),a[8]||(a[8]=r('<p><span class="marginnote">数字实例：100 万行的「性别」列（NDV=2）只需 2 条位向量，每条 \\(10^6\\) 位 = 125 KB，总共 250 KB。同样 100 万行的主键列则要 100 万条向量、几乎全 0——前者位运算扫描飞快，后者纯属浪费。常见误区是以为位图「又小又快到处能用」，它其实只在低 NDV、少更新这一角占优。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不讲倒排词表。也不把位图连接索引（join index）写完，只点名星型可用。学习索引不替代位图的位运算。</p><p>后课默认：低 NDV 分析列可位图；高更新表慎用。倒排与全文：词项→位置列表，是搜索引擎与 <code>LIKE</code>/<code>@@</code> 的结构。</p><p>位图是行集合的特征函数，不是哈希索引。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>低 NDV 列用位向量做谓词交并，CPU 友好。</li><li>高更新与高 NDV 不适合；版本要与 MVCC 对齐。</li><li>倒排与全文下一课：词项列表而非维值。</li><li>出处：O&#39;Neil；压缩位图文献；Ramakrishnan and Gehrke。</li></ul>',7))])}const f=B(p,[["render",A]]);export{h as __pageData,f as default};
